expression:
local({
  code <- as.numeric(haven::zap_labels(GUC_Q2))
  other <- lookup_values(GUC_Q2_open1, lookup_respondent_other)
  carer <- code %in% c(6, 7) | other %in% "Other carer"
  primary <- as.numeric(haven::zap_labels(GUC_Q3)) %in% c(1, 3)
  items <- sapply(list(GUC_Q31_1, GUC_Q31_2, GUC_Q31_3, GUC_Q31_4, GUC_Q31_5, GUC_Q31_6), function(x) {
    as.numeric(haven::zap_labels(x))
  })
  items[!items %in% 1:5] <- NA
  if_else(!carer | primary, rowSums(5 - items), NA_real_)
})
